public class InnerTableIcebergTableInputFactory(Action<Humidifier.Glue.TableTypes.IcebergTableInput> factoryAction = null) : SubResourceFactory<Humidifier.Glue.TableTypes.IcebergTableInput>
{

    internal InnerTableIcebergSchemaFactory SchemaFactory { get; set; }

    internal InnerTableIcebergSortOrderFactory WriteOrderFactory { get; set; }

    internal InnerTableIcebergPartitionSpecFactory PartitionSpecFactory { get; set; }

    protected override Humidifier.Glue.TableTypes.IcebergTableInput Create()
    {
        var icebergTableInputResult = CreateIcebergTableInput();
        factoryAction?.Invoke(icebergTableInputResult);

        return icebergTableInputResult;
    }

    private Humidifier.Glue.TableTypes.IcebergTableInput CreateIcebergTableInput()
    {
        var icebergTableInputResult = new Humidifier.Glue.TableTypes.IcebergTableInput();

        return icebergTableInputResult;
    }
    public override void CreateChildren(Humidifier.Glue.TableTypes.IcebergTableInput result)
    {
        base.CreateChildren(result);

        result.Schema ??= SchemaFactory?.Build();
        result.WriteOrder ??= WriteOrderFactory?.Build();
        result.PartitionSpec ??= PartitionSpecFactory?.Build();
    }

} // End Of Class

